INSERT INTO public.detalles_proyectos VALUES (298, '2025-11-01', 'Pregrado', 'Se llevó a cabo un proyecto titulado "Sistema de Control de Acceso al Laboratorio Informático de la E.T. Pedro García Leal", en el cual se analizaron y priorizaron las necesidades tecnológicas de la institución mediante un diagnóstico situacional, donde se procuró resolver el problema principal de acceso no autorizado al laboratorio informático, creando una solución viable con los recursos disponibles que se tenían. Se implementó el proyecto haciendo uso de la metodología RUP (Rational Unified Process), mediante el diagnóstico situacional y la entrevista realizada a la directora de la institución, se llegó a la conclusión de desarrollar un programa en Python con CustomTkinter como interfaz gráfica y el uso de SQLite3 como gestor de base de datos, permitiendo registros y la generación de reportes automatizados', 1, 'Institución: Escuela Técnica “Pedro García Leal”', 'Sistema, Laboratorio, Metodología, Python, Base de Datos', '2026-10-20 00:09:16.424521', NULL, NULL, 'Implementar un sistema de información para controlar el acceso al laboratorio informático de la E.T ''Pedro García Leal''.', true, '[-0.04802049,0.08241461,0.04096913,-0.06105789,-0.01766896,-0.09236619,0.0711292,0.02031967,0.01890457,0.05595623,-0.00920531,-0.02272485,0.02059494,-0.13279442,-0.0318812,0.06297825,-0.07630323,-0.01375807,0.0099112,0.00948175,0.00968498,-0.03521127,-0.07544197,0.01248214,-0.12134208,0.00387444,-0.04418208,0.01842221,0.01954649,-0.02128771,-0.02559008,-0.01267846,-0.0248859,-0.00320549,-0.04389126,0.06587979,-0.0505209,-0.05432762,-0.03175641,0.00871707,0.01969249,-0.003764,-0.0163157,0.03136428,-0.05021678,-0.06372276,0.04090822,-0.07507379,-0.00127638,0.06144736,-0.01605412,0.00216017,-0.01715788,-0.08637809,-0.0138896,0.09112923,0.06152673,0.09028432,-0.04903388,0.02067389,-0.05196354,-0.01924399,-0.03747137,-0.01235071,0.1368848,0.00536589,-0.04772822,-0.03702116,0.06719165,-0.04619094,0.05380