INSERT INTO public.detalles_proyectos VALUES (254, '2025-11-26', 'Pregrado', 'Este proyecto propone el desarrollo e implementación de un sistema web para la gestión del talento humano del SAPNNAET, con el fin de modernizar y optimizar los procesos administrativos de la institución. A partir de un diagnóstico situacional, se identificaron problemáticas como el uso de sistemas obsoletos, la falta de centralización de la información y la limitada capacitación del personal. La solución planteada consiste en una herramienta web que mejora la eficiencia, organización y seguridad en la gestión de datos del personal. Este proyecto se enmarca en la línea de desarrollo de sistemas del PNF en Informática con las líneas de investigación: Sistema de Información y Modelado de Datos. Con esto busca generar un impacto positivo en la operatividad institucional y en la atención a la comunidad', 1, 'SAPNNAET', 'Sistema Web, Gestión Integral, Talento humano, SAPNNAET', '2026-10-19 23:06:57.170925', NULL, NULL, 'Desarrollar e implementar el Sistema Web de gestión integral del Talento humano para el SAPNNAET.', true, '[-0.05925235,0.02243204,0.04646388,-0.03651422,-0.07236507,-0.11147079,0.11160877,0.01426153,0.02725952,0.06636309,-0.03503387,0.04682439,-0.02772456,-0.00580806,0.06960965,0.10481748,-0.09487597,-0.07430513,-0.08899103,0.05799228,-0.05324968,-0.04636382,-0.06111692,-0.0195106,-0.08664722,-0.02735559,-0.00604924,0.05713276,0.05271,0.03172051,0.03205279,-0.02741493,0.05717536,0.06705288,-0.0639454,0.09189409,0.01318032,-0.04322479,0.0614484,-0.03079094,-0.08444132,-0.07181706,-0.05724739,0.0373892,-0.03976056,0.05323422,0.00298193,-0.02766685,-0.07121774,0.01691582,-0.02029677,-0.01551319,-0.05078855,0.03077842,0.00643554,0.03775139,0.05144891,0.05338025,0.03973775,0.02829596,-0.01475963,0.02023796,-0.01285966,0.05674173,0.03375436,0.00977975,-0.07806706,-0.05337357,0.03090948,-0.02477366,0.087257,-0.01886552,-0.028563,0.02815923,-0.05253847,-0.00779258,0.06504514,-0.0278907