INSERT INTO public.detalles_proyectos VALUES (301, '2025-11-01', 'Pregrado', 'El Proyecto Socio Tecnológico desarrollado en la Escuela Técnica “Pedro García Leal” tiene el propósito de implantar un Sistema de Información destinado a solucionar las diversas problemáticas encontradas en el área de informática, comenzando con el diagnóstico situacional, donde a través de una entrevista estructurada se nos puso al tanto de los diversos desafíos que atraviesa la institución. Mediante el desarrollo de una jerarquización e identificación de necesidades se seleccionó la alternativa más factible, con la ayuda de los diferentes proyectos en el marco referencial se tuvo la idea de usar la metodología ágil SCRUM, en el desarrollo de la propuesta, tomando en cuenta lo antes expresado, se hizo una lista de requisitos funcionales la cual se utilizó durante los diversos sprints realizados en el transcurso del proyecto, finalmente se ejecutó exitosamente la implantación del sistema', 1, 'ESCUELA TÉCNICA: “PEDRO GARCÍA LEAL', 'programación, base de datos, sistema de información, SCRUM, informática, entrevista, sprint, implantación', '2026-10-20 00:09:16.704217', NULL, NULL, 'Brindar una educación técnica de la calidad de 1ero a 6to año.', true, '[-0.04869871,0.10391623,-0.00577592,0.00181036,-0.0244139,-0.07840818,0.10161741,0.01416135,-0.05326822,-0.05712482,0.01599829,-0.02229402,0.09683967,-0.0868886,0.03981991,-0.01751325,0.02351921,0.03853686,-0.02247352,0.04420423,-0.05103966,-0.02999255,0.01904979,0.03749735,-0.10652527,-0.01467757,0.04159022,-0.05377106,0.04540136,0.00684646,-0.06156276,-0.03765804,0.03771104,-7.342e-05,0.01173465,0.07307158,-0.00830147,0.04693308,-0.04450244,0.03709418,0.0159871,-0.09466633,-0.02475846,0.01932893,0.00364323,-0.08714368,-0.01577978,-0.01017001,-0.01907245,0.0139579,-0.11816736,-0.02574217,-0.03919013,-0.09641073,-0.02931142,0.07730994,0.05213689,0.01280103,0.05617216,0.03456456,-0.11269711,-0.01573699,0.0318557,-0.00232295,0.11878657,-0.00910