INSERT INTO public.detalles_proyectos VALUES (229, '2025-11-01', 'Pregrado', 'Implementación de un Sistema Integral de Gestión Administrativa para el taller Automotriz Inversiones “Dios es Amor 31” C.A, Municipio Valera, Estado Trujillo. El presente proyecto tiene como finalidad la implementación de un Sistema Integral de Gestión Administrativa para el Taller Automotriz “Dios es Amor 31” C.A, Municipio Valera, Estado Trujillo. Como tal, el objetivo de dicho proyecto es buscar solución a la problemática que presenta el taller automotriz inversiones “Dios es Amor 31” C.A, con respecto a la falta de un sistema administrativo, con la experiencia y conocimiento que poseen los autores que realizan este proyecto, y poniendo en práctica todo lo aprendido hasta ahora de lo que han visto en la carrera de informática, siempre cumpliendo los lineamientos establecidos por la ley y por el PNFI adjunto a la U.P.T.T “Mario Briceño Iragorry”-La Beatriz (de la cual los integrantes de este proyecto pertenecen)', 1, 'TALLER AUTOMOTRIZ INVERSIONES “DIOS ES AMOR 31” C.A', 'Sistema – internet - información -metodologías', '2026-10-19 22:37:13.125266', NULL, NULL, 'Desarrollar e implementar el SISTEMA INTEGRAL DE GESTIÓN ADMINISTRATIVO PARA EL TALLER AUTOMOTRIZ INVERSIONES “DIOS ES AMOR 31” C.A.', true, '[0.10951941,0.02241539,0.06103936,-0.00068417,0.03904475,-0.01284343,0.05662221,0.04784723,-0.03157055,-0.00225456,0.03000449,0.01251719,-0.03281334,-0.07731576,0.10486179,0.06919122,-0.07755568,-0.00264297,-0.12769088,0.02003049,-0.04903785,0.00929062,-0.09554482,-0.07582867,0.00727683,0.04232411,-0.01988377,0.01019154,0.03641104,0.03230051,0.00884068,-0.1074572,0.12042908,0.07525696,0.01084189,0.06826621,-0.03092242,-0.03617693,-0.00705988,-0.04718616,-0.03681803,-0.02506978,-0.04596141,-0.07117241,-0.01821015,-0.01256737,0.0052614,-0.06975317,-0.06742621,-0.00224043,-0.01845402,-0.01493055,0.02420543,0.03115043,-0.04305335,0.0565963,-0.00247572,0.07602012,0.01199102,0.05655114,-0.019318