INSERT INTO public.detalles_proyectos VALUES (283, '2025-11-01', 'Pregrado', 'El presente informe demuestra todo el desarrollo llevado a cabo para la elaboración de una Aplicación Web Informativa a base del uso de distintas herramientas y métodos para su logro, tomando como base de dicha Aplicación, el contenido del Parque Botánico, Flora, Fauna y sus Áreas, para la creación de un sitio web que esté disponible para el público general y pueda informarse desde la comodidad de sus casas o escritorios, todo lo que la comunidad de INPARQUES en el municipio Valera tiene para ofrecer, sumando también un importante acceso de Administración para el personal de la comunidad, con el objetivo de permitir que la página sea actualizable cada vez que sea necesario, aplicando incluso herramientas fuera de lo común con el desarrollo web como Canva para lograr la meta de ofrecer un producto de calidad', 1, 'Parque de Recreación Botánico La Beatriz', '', '2026-10-19 23:44:28.921378', NULL, NULL, 'Implementar en el Parque de Recreación Botánico La Beatriz una Aplicación Web que conserve el contenido a mostrar de la comunidad.', true, '[0.02818388,-0.00398044,0.02192613,0.01747512,0.05362659,0.04227379,0.05121664,-0.03168225,-0.06273364,0.03969817,-0.09572681,0.00352996,-0.04192001,0.02562245,0.09058751,0.02874946,0.07010746,-0.032341,-0.02881947,-0.01602754,0.03137367,-0.00206268,0.04771587,0.01092617,-0.17334434,-0.03237982,-0.09159998,0.02705143,0.03402779,0.00507628,0.02946332,-0.00999446,0.05698515,0.03321626,-0.02582609,0.02475729,-0.04637971,-0.00561477,0.03393826,0.04131246,-0.10636091,-0.04451837,-0.01877908,0.02626334,-0.01502701,0.1453603,0.01026381,-0.06165282,0.02607294,0.05733521,-0.00531667,-0.05677109,-0.04323878,-0.13435905,0.03859596,0.02575957,-0.06908999,0.04534953,0.02410258,0.02724979,-0.00490146,-0.0760532,-0.02982324,0.02917368,0.04342327,-0.02358291,-0.03162946,0.05930638,0.06075166,-0.10228158,0.0815346,0.01337949,0.01437098,-0.03994941,-0.02830399,-0.00665871,